<?php App\Models\Booking::whereDoesntHave('payments')->get()->each(function($b) { App\Models\Payment::create(['company_id' => $b->company_id, 'booking_id' => $b->id, 'receipt_number' => 'RCT-' . strtoupper(Str::random(6)), 'amount' => $b->booking_amount, 'payment_date' => $b->booking_date, 'payment_method' => 'cash', 'status' => 'pending_clearance', 'recorded_by_user_id' => $b->sales_user_id ?? 1, 'notes' => 'Initial Booking Token']); });
